@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

/* Typefaces — Italia */
@import "@fontsource/titillium-web/400.css";
@import "@fontsource/titillium-web/600.css";
@import "@fontsource/titillium-web/700.css";
@import "@fontsource/dm-mono/400.css";
@import "@fontsource/dm-mono/500.css";

@custom-variant dark (&:is(.dark *));

/* Scanned sources (Tailwind v4 content detection) */
@source "../../../../apps/**/*.{ts,tsx}";
@source "../**/*.{ts,tsx}";

@theme inline {
  /* Semantic colors (shadcn contract) */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary-hover: var(--primary-hover);
  --color-primary-light: var(--primary-light);
  --color-primary-100: var(--primary-100);
  --color-primary-50: var(--primary-50);
  --color-primary-850: var(--primary-850);
  /* Accessible primary for text/icons on light or muted surfaces (>= 4.5:1). */
  --color-primary-text: var(--primary-text);
  --color-secondary: var(--secondary);
  --color-secondary-dark: var(--secondary-dark);
  --color-secondary-50: var(--secondary-50);
  --color-secondary-850: var(--secondary-850);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-text-disabled: var(--text-disabled);
  --color-neutral-300: var(--neutral-300);
  --color-menu-item: var(--menu-item);
  --color-action-hover: var(--action-hover);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-input-border: var(--input-border);
  --color-ring: var(--ring);
  --color-tooltip: var(--tooltip);
  --color-tooltip-foreground: var(--tooltip-foreground);

  /* Status: main (fill/icon) + dark (hover) + light + muted surface + strong text */
  --color-destructive-accent: var(--destructive-accent);
  --color-destructive-dark: var(--destructive-dark);
  --color-destructive-light: var(--destructive-light);
  --color-destructive-muted: var(--destructive-muted);
  --color-destructive-strong: var(--destructive-strong);
  --color-success-accent: var(--success-accent);
  --color-success-dark: var(--success-dark);
  --color-success-light: var(--success-light);
  --color-success-muted: var(--success-muted);
  --color-success-strong: var(--success-strong);
  --color-warning-accent: var(--warning-accent);
  --color-warning-dark: var(--warning-dark);
  --color-warning-light: var(--warning-light);
  --color-warning-muted: var(--warning-muted);
  --color-warning-strong: var(--warning-strong);
  --color-info-accent: var(--info-accent);
  --color-info-dark: var(--info-dark);
  --color-info-light: var(--info-light);
  --color-info-muted: var(--info-muted);
  --color-info-strong: var(--info-strong);

  /* Status colors (additive to shadcn) */
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);

  /* Brand tokens (additive) */
  --color-brand: var(--brand);
  --color-brand-foreground: var(--brand-foreground);
  --color-eu: var(--eu);
  --color-eu-foreground: var(--eu-foreground);
  --color-indigo: var(--indigo);
  --color-check-iban: var(--check-iban);

  /* Italia palette */
  --color-italia-50: var(--italia-50);
  --color-italia-100: var(--italia-100);
  --color-italia-200: var(--italia-200);
  --color-italia-300: var(--italia-300);
  --color-italia-400: var(--italia-400);
  --color-italia-500: var(--italia-500);
  --color-italia-600: var(--italia-600);
  --color-italia-700: var(--italia-700);
  --color-italia-800: var(--italia-800);
  --color-italia-900: var(--italia-900);

  /* Charts + sidebar (required by shadcn) */
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* Typography */
  --font-sans: "Titillium Web", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "DM Mono", ui-monospace, monospace;
  --font-heading: var(--font-sans);

  /* Radii — MUI shape scale */
  --radius: 0.5rem; /* 8px */
  --radius-sm: 0.25rem; /* 4px  — buttons */
  --radius-md: 0.375rem; /* 6px  — tags/chips */
  --radius-lg: 0.5rem; /* 8px  — cards */
  --radius-xl: 1rem; /* 16px */
  --radius-2xl: 1.5rem; /* 24px */

  /* Breakpoints — Bootstrap Italia inspired */
  --breakpoint-sm: 40rem; /* 640 */
  --breakpoint-md: 56.25rem; /* 900 */
  --breakpoint-lg: 75rem; /* 1200 */
  --breakpoint-xl: 96rem; /* 1536 */
  --breakpoint-2xl: 120rem; /* 1920 */

  /* Elevations */
  --shadow-elevation-4:
    0px 2px 4px -1px color-mix(in srgb, var(--shadow-color) 10%, transparent),
    0px 4px 5px color-mix(in srgb, var(--shadow-color) 5%, transparent),
    0px 1px 10px color-mix(in srgb, var(--shadow-color) 10%, transparent);
  --shadow-elevation-8:
    0px 8px 10px -5px color-mix(in srgb, var(--shadow-color) 10%, transparent),
    0px 16px 24px 2px color-mix(in srgb, var(--shadow-color) 5%, transparent),
    0px 6px 30px 5px color-mix(in srgb, var(--shadow-color) 10%, transparent);
  --shadow-elevation-16:
    0px 16px 24px -8px color-mix(in srgb, var(--shadow-color) 12%, transparent),
    0px 8px 32px 4px color-mix(in srgb, var(--shadow-color) 8%, transparent),
    0px 4px 48px 8px color-mix(in srgb, var(--shadow-color) 12%, transparent);
}

:root {
  --shadow-color: #002b55;

  /* Surfaces — themeNext (paletteNext) */
  --background: #ffffff;
  --foreground: #0e0f13;
  --card: #ffffff;
  --card-foreground: #0e0f13;
  --popover: #ffffff;
  --popover-foreground: #0e0f13;
  --muted: #f4f5f8;
  --muted-foreground: #555c70;
  --text-disabled: #99a3c1;
  --neutral-300: #bbc2d6;
  --accent: #e3f2fd;
  --accent-foreground: #0e0f13;
  --border: #e8ebf1;
  --input: #e8ebf1;
  --input-border: #636b82;
  --ring: #0b3ee3;
  --tooltip: #455b71;
  --tooltip-foreground: #ffffff;
  --overlay: rgb(14 15 19 / 35%);
  --menu-item: #17324d;

  /* Primary — colors.blue[500] (paletteNext.primary.main) */
  --primary: #0b3ee3;
  --primary-light: #3c65e9;
  --primary-hover: #0932b6;
  --primary-100: #c4dcf5;
  --primary-50: #e7ecfc;
  --primary-850: #031344;
  --primary-foreground: #ffffff;
  /* #0b3ee3 is ~7.4:1 on white: safe for text as well. */
  --primary-text: #0b3ee3;

  /* Secondary — turquoise (absent in paletteNext: legacy DS value) */
  --secondary: #00c5ca;
  --secondary-dark: #00a7ac;
  --secondary-50: #dbf9fa;
  --secondary-850: #003b3d;
  --secondary-foreground: #0e0f13;

  /* Interaction tints — DS intent adapted to the themeNext primary */
  --action-hover: rgb(23 50 77 / 8%);
  --primary-action-hover: rgb(11 62 227 / 12%);

  /* Status — main (fill/icon/border) + dark (hover) + light + muted surface + strong text */
  --destructive: #d13333;
  --destructive-dark: #a82929;
  --destructive-light: #ff4040;
  --destructive-accent: #d13333;
  --destructive-muted: #ffe0e0;
  --destructive-strong: #761f1f;
  --destructive-foreground: #ffffff;

  --success: #6cc66a;
  --success-dark: #5ca85a;
  --success-light: #89d188;
  --success-accent: #6cc66a;
  --success-muted: #e1f4e1;
  --success-strong: #224021;
  --success-foreground: #0e0f13;

  --warning: #ffc824;
  --warning-dark: #d9ad3c;
  --warning-light: #ffd56b;
  --warning-accent: #ffc824;
  --warning-muted: #fff5da;
  --warning-strong: #614c15;
  --warning-foreground: #0e0f13;

  --info: #6bcffb;
  --info-dark: #5bb0d5;
  --info-light: #89d9fc;
  --info-accent: #6bcffb;
  --info-muted: #e1f5fe;
  --info-strong: #215c76;
  --info-foreground: #0e0f13;

  /* Brand */
  --brand: #0066cc;
  --brand-foreground: #ffffff;
  --eu: #264ca4;
  --eu-foreground: #ffffff;
  --indigo: #3f51b5;
  --check-iban: #008ca8;

  /* Illustrations (colors from mui `useIllustrationColors`) */
  --illustration-primary: #0b3ee3;
  --illustration-secondary: #ced8f9;

  /* Italia palette */
  --italia-50: #e3f2fd;
  --italia-100: #bbdefb;
  --italia-200: #90caf9;
  --italia-300: #1976d2;
  --italia-400: #42a5f5;
  --italia-500: #0073e6;
  --italia-600: #1e88e5;
  --italia-700: #0059b2;
  --italia-800: #1565c0;
  --italia-900: #0d47a1;

  /* Charts */
  --chart-1: #0b3ee3;
  --chart-2: #00c5ca;
  --chart-3: #6cc66a;
  --chart-4: #ffc824;
  --chart-5: #d13333;

  /* Sidebar */
  --sidebar: #ffffff;
  --sidebar-foreground: #0e0f13;
  --sidebar-primary: #0b3ee3;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e3f2fd;
  --sidebar-accent-foreground: #0e0f13;
  --sidebar-border: #e8ebf1;
  --sidebar-ring: #0b3ee3;
}

.dark {
  --shadow-color: #000000;

  --background: #121212;
  --foreground: #ffffff;
  --card: #252525;
  --card-foreground: #ffffff;
  --popover: #252525;
  --popover-foreground: #ffffff;
  --muted: #2a2a2a;
  --muted-foreground: #a2adb8;
  --accent: #1e3a5f;
  --accent-foreground: #ffffff;
  --border: rgba(255, 255, 255, 0.12);
  --input: rgba(255, 255, 255, 0.16);
  --input-border: rgb(255 255 255 / 42%);
  --ring: #3da2ff;
  --tooltip: #2a2a2a;
  --tooltip-foreground: #ffffff;
  --overlay: color-mix(in srgb, #000000 70%, transparent);

  --primary: #3da2ff;
  --primary-light: #64b5ff;
  --primary-hover: #5cb0ff;
  --primary-100: #123354;
  --primary-50: #0d2135;
  --primary-850: #e3f2fd;
  --primary-foreground: #0b1f33;
  --primary-text: #3da2ff;

  --secondary: #00c5ca;
  --secondary-dark: #00a7ac;
  --secondary-50: #0a2b2c;
  --secondary-850: #dbf9fa;
  --secondary-foreground: #0b1f33;

  --text-disabled: #7f8a99;
  --neutral-300: rgb(255 255 255 / 24%);
  --menu-item: #17324d;
  --action-hover: rgb(255 255 255 / 8%);
  --primary-action-hover: rgb(61 162 255 / 16%);

  --destructive: #ff8a8a;
  --destructive-dark: #ff6b6b;
  --destructive-light: #ffb3b3;
  --destructive-accent: #ff8a8a;
  --destructive-muted: rgb(255 138 138 / 16%);
  --destructive-strong: #ffb3b3;
  --destructive-foreground: #3b0a0a;

  --success: #8ed88c;
  --success-dark: #6fbf6d;
  --success-light: #b5e2b4;
  --success-accent: #8ed88c;
  --success-muted: rgb(142 216 140 / 16%);
  --success-strong: #b5e2b4;
  --success-foreground: #10240f;

  --warning: #ffd97a;
  --warning-dark: #e0b84f;
  --warning-light: #ffe5a3;
  --warning-accent: #ffd97a;
  --warning-muted: rgb(255 217 122 / 16%);
  --warning-strong: #ffe5a3;
  --warning-foreground: #3a2c00;

  --info: #8fd8f5;
  --info-dark: #64b5d8;
  --info-light: #b3e7fa;
  --info-accent: #8fd8f5;
  --info-muted: rgb(143 216 245 / 16%);
  --info-strong: #b3e7fa;
  --info-foreground: #06232e;

  --brand: #4d9fff;
  --brand-foreground: #0b1f33;
  --eu: #7f9fe0;
  --eu-foreground: #0b1f33;
  --indigo: #7986cb;
  --check-iban: #4dd0e1;

  --illustration-primary: #ffffff;
  --illustration-secondary: #6d8bee;

  --italia-50: #0d2135;
  --italia-100: #123354;
  --italia-200: #17456f;
  --italia-300: #1d5c93;
  --italia-400: #2f7fc4;
  --italia-500: #3da2ff;
  --italia-600: #64b5ff;
  --italia-700: #8ec8ff;
  --italia-800: #b8dcff;
  --italia-900: #e3f2fd;

  --chart-1: #3da2ff;
  --chart-2: #00c5ca;
  --chart-3: #8ed88c;
  --chart-4: #ffd97a;
  --chart-5: #ff8a8a;

  --sidebar: #1a1a1a;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #3da2ff;
  --sidebar-primary-foreground: #0b1f33;
  --sidebar-accent: #1e3a5f;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgba(255, 255, 255, 0.12);
  --sidebar-ring: #3da2ff;
}

/* Type scale — Italia (responsive at sm = 640px, as in mui-italia) */
@utility text-headline {
  font-family: var(--font-sans);
  font-weight: 700;
  font-size: 3.625rem; /* 58px */
  line-height: 1.1;
}
@utility text-h1 {
  font-family: var(--font-sans);
  font-weight: 700;
  font-size: 2.625rem; /* 42px */
  line-height: 1.1;
  @media (width >= 40rem) {
    font-size: 3.125rem; /* 50px */
    line-height: 1.08;
  }
}
@utility text-h2 {
  font-family: var(--font-sans);
  font-weight: 700;
  font-size: 2.25rem; /* 36px */
  line-height: 1.1;
  @media (width >= 40rem) {
    font-size: 2.75rem; /* 44px */
    line-height: 1.09;
  }
}
@utility text-h3 {
  font-family: var(--font-sans);
  font-weight: 700;
  font-size: 2rem; /* 32px */
  line-height: 1.125;
  @media (width >= 40rem) {
    font-size: 2.375rem; /* 38px */
    line-height: 1.1;
  }
}
@utility text-h4 {
  font-family: var(--font-sans);
  font-weight: 700;
  font-size: 1.75rem; /* 28px */
  line-height: 1.15;
  @media (width >= 40rem) {
    font-size: 2rem; /* 32px */
    line-height: 1.125;
  }
}
@utility text-h5 {
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 1.5rem; /* 24px */
  line-height: 1.15;
  @media (width >= 40rem) {
    font-size: 1.75rem; /* 28px */
    line-height: 1.5;
  }
}
@utility text-h6 {
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 1.375rem; /* 22px */
  line-height: 1.18;
  @media (width >= 40rem) {
    font-size: 1.5rem; /* 24px */
    line-height: 1.15;
  }
}
@utility text-sidenav {
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 1.125rem; /* 18px */
  line-height: 1.35;
}
@utility text-body-lg {
  font-size: 1.125rem; /* 18px */
  line-height: 1.5;
  font-weight: 400;
}
@utility text-body {
  font-size: 1rem; /* 16px */
  line-height: 1.4;
  font-weight: 400;
  letter-spacing: 0.15px;
}
@utility text-caption {
  font-size: 0.875rem; /* 14px */
  line-height: 1.4;
  font-weight: 400;
}
@utility text-caption-strong {
  font-size: 0.875rem; /* 14px */
  line-height: 1.4;
  font-weight: 600;
}
@utility text-overline {
  font-size: 0.875rem; /* 14px */
  line-height: 1.15;
  font-weight: 700;
  letter-spacing: 1px;
}
@utility text-mono {
  font-family: var(--font-mono);
  font-size: 1rem; /* 16px */
  line-height: 1.4;
  letter-spacing: 0.15px;
}

/* Reusable Italia focus ring */
@utility focus-ring {
  &:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
    border-radius: var(--radius-sm);
    box-shadow: none;
  }
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-sans);
    font-size: 1rem;
    line-height: 1.4;
  }
  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}
